function Nav({id,icon,tab,go}){return <button className={tab===id?"active":""} onClick={()=>go(id)}><span>{icon}</span>{id[0].toUpperCase()+id.slice(1)}</button>}
function Hero({kicker,title,description,action}){return <div className="page-hero"><div><small>{kicker}</small><h1>{title}</h1><p>{description}</p></div>{action&&<button onClick={action}>＋ {action.name.replaceAll("_"," ")}</button>}</div>}
function activate(event, action){if(event.key === "Enter" || event.key === " "){event.preventDefault();action()}}
function Overview({user,pipeline,contracted,tasks,go}){const stats=[["Total pipeline",money(pipeline),"Across all active source stages","deals"],["Contract sent",money(contracted),"Late-stage value, not won revenue","deals"],["Active deals",deals.length,`${companies.length} connected companies`,`deals`],["Open tasks",tasks.filter(x=>x.status!=="Completed").length,`${tasks.filter(x=>x.status==="Completed").length} completed`,`tasks`]];return <><Hero title={`Good morning, ${user.name.split(" ")[0]} ✦`} description="Here’s what’s happening across your customer relationships."/><div className="metric-grid">{stats.map(x=><article className="overview-link-card" role="button" tabIndex={0} aria-label={`Open ${x[0]}`} onClick={()=>go(x[3])} onKeyDown={event=>activate(event,()=>go(x[3]))} key={x[0]}><span>{x[0]}<i>▥</i></span><strong>{x[1]}</strong><small>{x[2]}</small><em>View {x[3]}</em></article>)}</div><div className="overview-panels"><Panel title="Sales pipeline" sub="Deal volume and value by source stage" onClick={()=>go("deals")}><Pipeline go={go}/></Panel><Panel title="Pipeline trend" sub="Value by latest activity month" onClick={()=>go("analytics")}><Trend/></Panel><Panel title="Recent activity" sub="Latest connected touchpoints" onClick={()=>go("activity")}><CompactActivity/></Panel><Panel title="Top companies" sub="Ranked by connected pipeline" onClick={()=>go("companies")}><TopCompanies go={go}/></Panel></div></>}
function Companies({data,select}){return <><Hero kicker="Relationships" title="Company directory" description="Explore every organization and its commercial context." action={function Add_company(){}}/><div className="directory-tools"><label>⌕ Search companies…</label><select><option>All industries</option></select><span>{data.length} companies</span></div><div className="company-grid">{data.map(c=>{const related=deals.filter(d=>d.domain===c.domain),people=contacts.filter(x=>x.domain===c.domain);return <article key={c.id} onClick={()=>select({...c,type:"Company"})}><header><b>{initials(c.name)}</b><em>Active</em></header><h2>{c.name}</h2><p>{c.industry} · {c.city}</p><hr/><div><span>Pipeline<strong>{money(related.reduce((s,d)=>s+d.amount,0))}</strong></span><span>Deals<strong>{related.length}</strong></span><span>People<strong>{people.length}</strong></span></div><button>Open company ↗</button></article>})}</div></>}
function Contacts({data,select}){return <><Hero kicker="Relationships" title="People directory" description="Understand the people behind every customer relationship." action={function Add_contact(){}}/><div className="directory-tools"><label>⌕ Search people, roles, or companies…</label><span>{data.length} contacts</span></div><section className="people-list">{data.map(c=>{const record={...c,name:`${c.first} ${c.last}`,type:"Contact"};return <article key={c.id} onClick={()=>select(record)}><b>{c.first[0]}{c.last[0]}</b><p><strong>{c.first} {c.last}</strong><small>{c.role}</small></p><p><strong>{c.company}</strong><small>{c.email}</small></p><button onClick={event=>{event.stopPropagation();select(record)}}>✉ Email</button><i>↗</i></article>})}</section></>}
function Deals({data,select,addDeal}){const [open,setOpen]=useState(false);const [dealQuery,setDealQuery]=useState("");const [stageFilter,setStageFilter]=useState("All stages");const [dragging,setDragging]=useState(null);const stages=["Appointment scheduled","Qualified to buy","Contract sent"];const normalizedQuery=dealQuery.trim().toLowerCase();const filteredDeals=data.filter(deal=>(stageFilter==="All stages"||deal.stage===stageFilter)&&(!normalizedQuery||[deal.name,deal.company,deal.stage,deal.close,String(deal.amount)].join(" ").toLowerCase().includes(normalizedQuery)));const visibleStages=stageFilter==="All stages"?stages:[stageFilter];useEffect(()=>{document.body.style.overflow=open?"hidden":"";return()=>{document.body.style.overflow=""}},[open]);useEffect(()=>{const showForm=()=>setOpen(true);window.addEventListener("clario-open-deal-form",showForm);return()=>window.removeEventListener("clario-open-deal-form",showForm)},[]);function submit(event){event.preventDefault();const values=new FormData(event.currentTarget),company=companies.find(item=>item.id===values.get("companyId"));if(!company)return;addDeal({id:`deal_custom_${Date.now()}`,name:values.get("name").trim(),companyId:company.id,company:company.name,domain:company.domain,pipeline:"Sales pipeline",stage:values.get("stage"),amount:Number(values.get("amount")),close:values.get("close")});setOpen(false)}function drop(stage){if(dragging&&dragging.stage!==stage){window.dispatchEvent(new CustomEvent("clario-deal-moved",{detail:{id:dragging.id,stage}}))}setDragging(null)}return <><Hero kicker="Revenue" title="Sales pipeline" description="Track opportunities through the source-supported deal stages." action={function Add_deal(){setOpen(true)}}/><div className="directory-tools"><label className="deal-search">⌕<input value={dealQuery} onChange={event=>setDealQuery(event.target.value)} placeholder="Search deals…" aria-label="Search deals"/></label><select value={stageFilter} onChange={event=>setStageFilter(event.target.value)} aria-label="Filter deals by stage"><option>All stages</option>{stages.map(stage=><option key={stage}>{stage}</option>)}</select><span>{filteredDeals.length} deals · {money(filteredDeals.reduce((sum,deal)=>sum+deal.amount,0))}</span></div><div className={`pipeline-board ${visibleStages.length===1?"single-stage":""}`}>{visibleStages.map(stage=>{const rows=filteredDeals.filter(deal=>deal.stage===stage);return <section className={dragging?"drop-ready":""} onDragOver={event=>event.preventDefault()} onDrop={()=>drop(stage)} key={stage}><header><h3>{stage}</h3><b>{rows.length}</b><small>{money(rows.reduce((sum,deal)=>sum+deal.amount,0))} pipeline</small></header>{rows.length?rows.map(deal=><article draggable onDragStart={()=>setDragging(deal)} onDragEnd={()=>setDragging(null)} className={dragging?.id===deal.id?"is-dragging":""} key={deal.id} onClick={()=>select({...deal,type:"Deal"})}><h4>{deal.name}</h4><p>{deal.company}</p><strong>{money(deal.amount)}</strong><small>{deal.close}</small></article>):<div className="deal-empty">No deals match these filters.</div>}</section>})}</div>{open&&<div className="deal-modal-layer" role="presentation"><section className="deal-modal" role="dialog" aria-modal="true" aria-labelledby="new-deal-title"><header><div><small>New opportunity</small><h2 id="new-deal-title">Add a deal</h2><p>Enter the essential information to place this opportunity in the pipeline.</p></div><button type="button" onClick={()=>setOpen(false)} aria-label="Close form">×</button></header><form onSubmit={submit}><label>Deal name<input autoFocus name="name" required placeholder="e.g. Enterprise platform expansion"/></label><label>Company<select name="companyId" required defaultValue=""><option value="" disabled>Select a company</option>{companies.map(company=><option value={company.id} key={company.id}>{company.name}</option>)}</select></label><div className="deal-form-row"><label>Pipeline stage<select name="stage" required>{stages.map(stage=><option key={stage}>{stage}</option>)}</select></label><label>Deal amount<input name="amount" type="number" required min="1" step="1" placeholder="25000"/></label></div><label>Expected close date<input name="close" type="date" required/></label><footer><button type="button" onClick={()=>setOpen(false)}>Cancel</button><button className="save-deal" type="submit">Add deal <span>→</span></button></footer></form></section></div>}</>}
function Tasks({data,toggle}){return <><Hero kicker="Personal workspace" title="My work" description="Turn relationship intent into the next useful action." action={function Add_task(){}}/><div className="view-tabs"><b>All tasks</b><span>Today</span><span>Open</span><span>Overdue</span><span>Completed</span></div><div className="task-metrics"><Stat label="Due today" value={data.filter(x=>x.due==="Today").length}/><Stat label="Open" value={data.filter(x=>x.status!=="Completed").length}/><Stat label="Completed" value={data.filter(x=>x.status==="Completed").length}/></div><section className="task-list">{data.map(t=>{const deal=deals.find(d=>d.id===t.dealId);return <article className={t.status==="Completed"?"done":""} key={t.id}><button onClick={()=>toggle(t.id)}>{t.status==="Completed"?"✓":""}</button><strong>{t.title}</strong><span>{deal?.company} · {deal?.name}</span><em>{t.priority}</em><small>{t.due}</small><i>↗</i></article>})}</section></>}
function Activity({filter,setFilter}){const items=[...notes.map(x=>({type:"Note",title:"Note added",meta:x.body,company:x.company,date:x.date})),...emails.map(x=>{const c=contacts.find(c=>c.id===x.contactId);return {type:"Email",title:x.subject,meta:`${x.status} · ${c?.first} ${c?.last}`,company:c?.company,date:"Recent"}}),...calls.map(x=>({type:"Call",title:x.title,meta:`${x.status} · ${x.contact}`,company:x.contact,date:x.date})),...initialTasks.map(x=>{const d=deals.find(d=>d.id===x.dealId);return {type:"Task",title:x.title,meta:`${x.status} · ${d?.name}`,company:d?.company,date:x.due}})];const shown=filter==="All"?items:items.filter(x=>x.type===filter);return <><Hero kicker="Relationships" title="Relationship timeline" description="Everything happening across your connected customer records."/><div className="view-tabs">{["All","Note","Email","Call","Task"].map(x=><button className={filter===x?"active":""} onClick={()=>setFilter(x)} key={x}>{x}</button>)}</div><section className="timeline">{shown.map((x,i)=><article key={`${x.type}-${i}`}><b>{x.type[0]}</b><time>{x.date}</time><p><strong>{x.title}</strong><small>{x.meta}</small></p><a>{x.company} ↗</a></article>)}</section></>}
