function Pipeline({go}){const stages=["Appointment scheduled","Qualified to buy","Contract sent"],total=deals.reduce((sum,d)=>sum+d.amount,0),max=Math.max(...stages.map(s=>deals.filter(d=>d.stage===s).reduce((sum,d)=>sum+d.amount,0)));return <div className="pipeline-lines">{stages.map(s=>{const rows=deals.filter(d=>d.stage===s),value=rows.reduce((sum,d)=>sum+d.amount,0),percentage=total?((value/total)*100).toFixed(1):0;return <button className="pipeline-stage-link" key={s} onClick={event=>{event.stopPropagation();go?.("deals")}} aria-label={`${s}, ${rows.length} deals, ${money(value)} pipeline value`}><p><b>{s}</b><small>{rows.length} deals · {percentage}% of pipeline</small></p><span><i style={{width:`${max?(value/max)*100:0}%`}}/></span><strong>{money(value)}</strong><em className="data-tooltip"><b>{s}</b><small>{rows.length} deals · {money(value)} pipeline value</small><small>{percentage}% of total · Average {money(rows.length?value/rows.length:0)}</small></em></button>})}</div>}
