function TopBars(){return <div className="top-bars">{companies.map(c=>{const v=deals.find(d=>d.domain===c.domain)?.amount||0;return <div key={c.id}><span>{c.name}</span><i><b style={{width:`${v/12}%`}}/></i><strong>{money(v)}</strong></div>})}</div>}
