function CompanyDetail({company,back,contactsData=contacts}){const relatedContacts=contactsData.filter(item=>item.companyId===company.id),relatedDeals=deals.filter(item=>item.companyId===company.id),relatedNotes=notes.filter(item=>item.companyId===company.id);const fields=[["Website",company.website||company.domain],["Phone",company.phone],["Email",company.email],["Industry",company.industry],["Location",[company.city,company.state,company.country].filter(Boolean).join(", ")],["Company size",company.companySize],["Lifecycle",company.lifecycleStatus],["Source",company.source],["Annual revenue",company.annualRevenue?money(company.annualRevenue):null],["Notes",company.notes]];return <div className="company-360"><button className="back" onClick={back}>← Companies</button><header className="company-profile"><b>{initials(company.name)}</b><div><small>{company.sourceType==="clarion-ui"?"Clarion company":"Company"}</small><h1>{company.name}</h1><p>{company.domain||company.industry||"New customer relationship"}</p></div></header><div className="company-360-grid"><section className="data-panel"><h2>Company information</h2>{fields.filter(([,value])=>value).map(([label,value])=><p key={label}><span>{label}</span><strong>{value}</strong></p>)}</section><section className="data-panel company-relationship-summary"><h2>Relationship overview</h2><div><span>Contacts<strong>{relatedContacts.length}</strong></span><span>Deals<strong>{relatedDeals.length}</strong></span><span>Pipeline<strong>{money(relatedDeals.reduce((sum,deal)=>sum+deal.amount,0))}</strong></span></div>{!relatedContacts.length&&<article><b>No contacts yet</b><p>Contacts will appear as people are connected to this company.</p></article>}{!relatedDeals.length&&<article><b>No deals yet</b><p>Create an opportunity when this relationship enters the pipeline.</p></article>}{!relatedNotes.length&&<article><b>No activity yet</b><p>Activity will appear here as the relationship develops.</p></article>}</section></div></div>}

function ContactDetail({contact,back,companiesData=companies}){const [section,setSection]=useState("Overview");const company=companiesData.find(item=>item.id===contact.companyId)||{name:contact.company,domain:contact.domain};const relatedDeals=deals.filter(item=>item.companyId===contact.companyId);const relatedEmails=emails.filter(item=>item.contactId===contact.id);const relatedCalls=calls.filter(item=>item.contactId===contact.id);const dealIds=new Set(relatedDeals.map(item=>item.id));const relatedTasks=initialTasks.filter(item=>dealIds.has(item.dealId));const sections=["Overview","Deals","Emails","Calls","Tasks","Activity"];return <div className="contact-360"><button className="back" onClick={back}>← Contacts</button><header className="contact-profile"><span>{contact.first[0]}{contact.last[0]}</span><div><small>Contact</small><h1>{contact.name}</h1><p>{contact.role} · {company?.name}</p></div><div className="contact-actions"><a href={`tel:${contact.phone}`}>☎ Call</a><a className="primary" href={`mailto:${contact.email}`}>✉ Email</a></div></header><nav className="contact-tabs">{sections.map(item=><button className={section===item?"active":""} onClick={()=>setSection(item)} key={item}>{item}</button>)}</nav>{section==="Overview"&&<div className="contact-overview"><section className="data-panel contact-info"><h2>Contact information</h2><Info icon="✉" label="Work email" value={contact.email}/><Info icon="☎" label="Phone" value={contact.phone}/><Info icon="▥" label="Company" value={company?.name||"Unlinked"}/></section><section className="data-panel related-deals"><h2>Related deals</h2><p>Opportunities at {company?.name}</p>{relatedDeals.map(deal=><article key={deal.id}><div><strong>{deal.name}</strong><small>{deal.stage}</small></div><b>{money(deal.amount)}</b></article>)}</section></div>}{section==="Deals"&&<DetailList title="Related deals" rows={relatedDeals.map(x=>[x.name,x.stage,money(x.amount)])}/>} {section==="Emails"&&<DetailList title="Recent emails" rows={relatedEmails.map(x=>[x.subject,`${x.direction} · ${x.body}`,x.status])}/>} {section==="Calls"&&<DetailList title="Recent calls" rows={relatedCalls.map(x=>[x.title,`${x.direction} · ${x.notes}`,x.status])}/>} {section==="Tasks"&&<DetailList title="Related tasks" rows={relatedTasks.map(x=>[x.title,x.notes,x.status])}/>} {section==="Activity"&&<DetailList title="Contact activity" rows={[...relatedEmails.map(x=>[x.subject,"Email",x.status]),...relatedCalls.map(x=>[x.title,"Call",x.status])]}/>} {section==="Overview"&&<DetailList title="Recent emails" rows={relatedEmails.slice(0,4).map(x=>[x.subject,`${x.direction} · ${x.body}`,x.status])}/>}</div>}
function Info({icon,label,value}){return <div className="info-row"><i>{icon}</i><p><small>{label}</small><strong>{value}</strong></p></div>}
function DetailList({title,rows}){return <section className="data-panel contact-detail-list"><h2>{title}</h2><p>Communication connected by canonical contact ID</p>{rows.length?rows.map((row,index)=><article key={`${row[0]}-${index}`}><b>{row[0][0]}</b><div><strong>{row[0]}</strong><small>{row[1]}</small></div><span>{row[2]}</span></article>):<div className="empty-related">No connected records for this contact.</div>}</section>}
